{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product and quarter, is the contract reservation a minimum delivery requirement (i.e., you must deliver at least that many units to the customer in that quarter, with any shortfall incurring the delay compensation), or is it an exact delivery target that must be met precisely?"
  ],
  "rationale": "The response asks for a single policy choice regarding the nature of the contract reservation (minimum vs. exact), which constitutes one semantically independent question."
}

{
  "action": "question",
