  "atomic_questions": [
    "When you deliver fewer units than the reservation in a given quarter, is the delay compensation charged only on the shortfall for that quarter (i.e., (reservation − delivered) × rate for that quarter), or does the shortfall carry forward so that units delivered in later quarters still incur compensation for each quarter they were late?"
  ],
  "rationale": "The response contains a single clarification question asking for a specific policy choice regarding how delay compensation is calculated (current quarter only vs. carry-forward)."
}

